import all, {categories} from './catalog.js';
import {demoStyles as themedStyles, componentDocument} from './preview.js';

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const paths={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',bookmark:'<path d="M6 4h12v17l-6-4-6 4z"/>',search:'<circle cx="10.7" cy="10.7" r="6.7"/><path d="m16 16 4.5 4.5"/>',sliders:'<path d="M4 7h7m4 0h5M4 17h3m4 0h9"/><circle cx="13" cy="7" r="2"/><circle cx="9" cy="17" r="2"/>',shuffle:'<path d="M3 5h3c5 0 7 14 12 14h3m-4-4 4 4-4 3M3 19h3c2 0 3-2 4-4m4-6c1-2 2-4 4-4h3m-4-3 4 3-4 4"/>','arrow-right':'<path d="M4 12h16m-6-6 6 6-6 6"/>','arrow-down':'<path d="M12 4v16m-6-6 6 6 6-6"/>',layers:'<path d="m12 3 9 5-9 5-9-5zM3 12l9 5 9-5M3 16l9 5 9-5"/>',list:'<path d="M8 6h13M8 12h13M8 18h13M3 6h.1M3 12h.1M3 18h.1"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',code:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6m-3-15-2 18"/>',replay:'<path d="M3 11a9 9 0 1 1 2 7M3 4v7h7"/>',monitor:'<rect x="2" y="3" width="20" height="14" rx="2"/><path d="M8 21h8m-4-4v4"/>',phone:'<rect x="6" y="2" width="12" height="20" rx="2"/><path d="M10 5h4m-3 14h2"/>',pause:'<path d="M8 5v14M16 5v14"/>',play:'<path d="m7 4 14 8-14 8z"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 15v6h16v-6"/>',button:'<rect x="3" y="6" width="18" height="12" rx="4"/><path d="M8 12h8"/>',navigation:'<path d="m3 3 7 18 3-8 8-3z"/>',forms:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M7 9h10M7 15h6"/>',type:'<path d="M4 5h16M12 5v15M8 20h8"/>',motion:'<path d="M3 8h8M3 12h5M3 16h8"/><circle cx="16" cy="12" r="6"/>',background:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="m3 16 6-5 4 3 4-7 4 5"/>',chart:'<path d="M3 3v18h18M7 15l4-5 4 2 6-7"/>',feedback:'<path d="M21 3H3v14h5l4 4 4-4h5zM7 8h10M7 12h6"/>',section:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18M9 9v12"/>',template:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 7h18M7 7v14M10 11h7M10 15h5"/>'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.spark}</svg>`;
function hydrateIcons(root=document){root.querySelectorAll('[data-icon]').forEach(n=>n.innerHTML=icon(n.dataset.icon))}
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const catOf=id=>categories.find(c=>c.id===id);
const featured=['ref-reveal-footer','ref-duration-capsule','ref-type-fall','ref-folio-folder','ref-newsletter-footer','ref-commit-calendar','ref-fused-toolbar','ref-selection-cards','physical-spring','studio-mask-reveal','moire-interference','adaptive-bento','drawn-route','shared-indicator','bento-grid','pill-tabs','floating-input','spotlight-card'];
all.sort((a,b)=>{let x=featured.indexOf(a.id),y=featured.indexOf(b.id);return (x<0?1000:x)-(y<0?1000:y)});
let saved=new Set();
let theme=matchMedia('(prefers-color-scheme:light)').matches?'light':'dark';
try{saved=new Set(JSON.parse(localStorage.getItem('noir-saved')||'[]'));theme=localStorage.getItem('noir-theme')||theme}catch{}
if(!['light','dark'].includes(theme))theme='dark';
document.documentElement.dataset.theme=theme;
const state={view:'all',category:'all',query:'',style:'all',sort:'featured',limit:18,density:'grid',collection:null};
let current=null,detailTab='preview',codeTab='html',demoSpeed=1,demoPaused=false,demoCanvas=theme,mobile=false,toastTimer;

function demoStyles(c){return themedStyles(c,demoCanvas)}
function exportScript(c){return c.js||''}
function fullExample(c){return componentDocument(c,{theme:demoCanvas==='grid'?theme:demoCanvas,canvas:demoCanvas,speed:demoSpeed,paused:demoPaused})}
function iframeDocument(c,thumbnail=false){return componentDocument(c,{theme:thumbnail?theme:demoCanvas==='grid'?theme:demoCanvas,canvas:thumbnail?theme:demoCanvas,speed:demoSpeed,paused:demoPaused})}
function updateThemeButton(){$('#themeToggle').innerHTML=theme==='dark'?'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/></svg>':'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M20 15A8.5 8.5 0 0 1 9 4a8.5 8.5 0 1 0 11 11Z"/></svg>';$('#themeToggle').setAttribute('aria-label',`Switch to ${theme==='dark'?'light':'dark'} mode`);$('#themeToggle').setAttribute('aria-pressed',String(theme==='light'));document.querySelector('meta[name="theme-color"]').content=theme==='dark'?'#090909':'#f8f8f8'}
function setTheme(value){theme=value;document.documentElement.dataset.theme=theme;try{localStorage.setItem('noir-theme',theme)}catch{}updateThemeButton();render();if(current){demoCanvas=theme;syncCanvasButtons();buildPreview();updateCode()}}
function syncCanvasButtons(){$$('[data-canvas]').forEach(b=>{const selected=b.dataset.canvas===demoCanvas;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected))})}
$('#themeToggle').onclick=()=>setTheme(theme==='dark'?'light':'dark');updateThemeButton();
matchMedia('(prefers-color-scheme:light)').addEventListener('change',e=>{let preference;try{preference=localStorage.getItem('noir-theme')}catch{}if(!preference)setTheme(e.matches?'light':'dark')});
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2500)}
function persistSaved(){try{localStorage.setItem('noir-saved',JSON.stringify([...saved]))}catch{notify('Saved for this visit. Browser storage is unavailable.')}updateCounts()}
function updateCounts(){$$('.total-count').forEach(n=>n.textContent=all.length);$$('.saved-count').forEach(n=>n.textContent=[...saved].filter(id=>all.some(c=>c.id===id)).length);$('#newCount').textContent=all.filter(c=>c.isNew).length}
function toggleSave(id){const c=all.find(c=>c.id===id);if(saved.has(id)){saved.delete(id);notify(`${c.name} removed from your collection`)}else{saved.add(id);notify(`${c.name} saved to your collection`)}persistSaved();$$(`.card-save[data-id="${id}"]`).forEach(b=>{b.classList.toggle('saved',saved.has(id));b.setAttribute('aria-label',`${saved.has(id)?'Unsave':'Save'} ${c.name}`);b.setAttribute('aria-pressed',saved.has(id))});if(current?.id===id)updateDetailSave();if(state.view==='saved')render()}
function normalizedStyle(c,style){const tags=c.tags.map(x=>x.toLowerCase());if(style==='animated')return tags.some(x=>/animated|motion|css animation/.test(x))||/@keyframes|requestAnimationFrame/.test(c.css+c.js);if(style==='interactive')return !!c.js||tags.includes('interactive');return tags.some(x=>x.includes(style))}
function filtered(){return all.filter(c=>(state.view!=='saved'||saved.has(c.id))&&(state.view!=='new'||c.isNew)&&(state.category==='all'||state.category===c.category)&&(!state.query||`${c.name} ${c.description} ${c.tags.join(' ')} ${catOf(c.category).name} ${c.inspiration?.name||''}`.toLowerCase().includes(state.query.toLowerCase()))&&(state.style==='all'||normalizedStyle(c,state.style))&&(!state.collection||state.collection.includes(c.category))).sort((a,b)=>state.sort==='az'?a.name.localeCompare(b.name):state.sort==='newest'?Number(b.isNew)-Number(a.isNew):0)}
const frameObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{const frame=entry.target;if(entry.isIntersecting){if(!frame.srcdoc){const c=all.find(c=>c.id===frame.dataset.id);frame.srcdoc=iframeDocument(c,true)}}else if(frame.srcdoc){frame.removeAttribute('srcdoc')}}),{rootMargin:'120px'});
function render(){frameObserver.disconnect();const items=filtered(),visible=items.slice(0,state.limit),grid=$('#componentGrid');grid.innerHTML=visible.map(c=>`<article class="component-card"><div class="card-preview"><iframe title="${escapeHTML(c.name)} preview" data-id="${c.id}" sandbox="allow-scripts" tabindex="-1" aria-hidden="true" loading="lazy"></iframe>${c.isNew?'<span class="card-new">New</span>':''}</div><div class="card-meta"><h3 class="card-title">${escapeHTML(c.name)}</h3><div class="card-subtitle"><span>${catOf(c.category).name}</span><i></i><span>${escapeHTML(c.tags[0]||'Customizable')}</span></div><div class="card-description">${escapeHTML(c.description)}</div><span class="card-arrow">↗</span></div><button class="card-open" data-id="${c.id}" aria-label="Explore ${escapeHTML(c.name)}"></button><button class="card-save ${saved.has(c.id)?'saved':''}" data-id="${c.id}" aria-label="${saved.has(c.id)?'Unsave':'Save'} ${escapeHTML(c.name)}" aria-pressed="${saved.has(c.id)}">${icon('bookmark')}</button></article>`).join('');grid.classList.toggle('list-view',state.density==='list');grid.querySelectorAll('iframe').forEach(f=>frameObserver.observe(f));$('#resultCount').textContent=`${items.length} ${items.length===1?'component':'components'} ${state.category!=='all'?`in ${catOf(state.category).name.toLowerCase()}`:state.view==='saved'?'saved':''}`;$('#loadMore').hidden=items.length<=state.limit;$('#loadRemaining').textContent=`${items.length-state.limit} more`;$('#emptyState').hidden=!!items.length;$('#libraryEnd').hidden=!items.length;$('#resetFilters').hidden=!(state.query||state.category!=='all'||state.style!=='all'||state.collection);$('#clearSearch').hidden=!state.query;
if(state.view==='saved'&&!items.length){$('#emptyTitle').textContent='No saved components';$('#emptyDescription').textContent='Use the bookmark on any component to start your collection. Saved in this browser.'}else{$('#emptyTitle').textContent='No components found';$('#emptyDescription').textContent='Try another search or explore a different category.'}
$$('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===state.view);if(b.getAttribute('role')==='tab')b.setAttribute('aria-selected',b.dataset.view===state.view)});$$('[data-category]').forEach(b=>b.classList.toggle('active',b.dataset.category===state.category));$('#categoryFilter').value=state.category;$('#styleFilter').value=state.style;$('#sortFilter').value=state.sort;$('#filterSearch').value=state.query;updateCounts();
}
function syncSidebar(){const compact=matchMedia('(max-width:800px)').matches;$('#sidebar').inert=compact&&!$('#sidebar').classList.contains('open')}
function closeMobile(){$('#sidebar').classList.remove('open');$('#mobileMenu').setAttribute('aria-expanded','false');syncSidebar()}
function scrollLibrary(){$('#library').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'})}
function setView(view,scroll=true){state.view=view;state.limit=18;state.collection=null;state.category='all';$('#collectionsPanel').hidden=true;$('#libraryTitle').innerHTML=view==='saved'?'Saved components':view==='new'?'New components':'All components';$('#sectionEyebrow').textContent=view==='saved'?'Your collection':view==='new'?'New additions':'The collection';$('#navLibrary').classList.add('active');$('#navCollections').classList.remove('active');render();closeMobile();if(scroll)scrollLibrary()}
function resetFilters(){Object.assign(state,{view:'all',query:'',category:'all',style:'all',collection:null,limit:18});setView('all',false);render()}

$('#categoryNav').innerHTML=categories.map(c=>`<button class="side-item" data-category="${c.id}"><span>${icon(c.icon)}</span><span>${c.name}</span><span class="side-count">${all.filter(x=>x.category===c.id).length}</span></button>`).join('');
$('#categoryFilter').insertAdjacentHTML('beforeend',categories.map(c=>`<option value="${c.id}">${c.name}</option>`).join(''));
hydrateIcons();
$$('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));
$$('[data-category]').forEach(b=>b.onclick=()=>{state.category=b.dataset.category;state.limit=18;state.collection=null;$('#collectionsPanel').hidden=true;$('#navLibrary').classList.add('active');$('#navCollections').classList.remove('active');$('#libraryTitle').innerHTML=escapeHTML(catOf(state.category).name);$('#sectionEyebrow').textContent='Explore the category';render();closeMobile();scrollLibrary()});
$('#filterSearch').oninput=e=>{state.query=e.target.value;state.limit=18;render()};
$('#clearSearch').onclick=()=>{state.query='';render();$('#filterSearch').focus()};
$('#categoryFilter').onchange=e=>{state.category=e.target.value;state.limit=18;render()};
$('#styleFilter').onchange=e=>{state.style=e.target.value;state.limit=18;render()};
$('#sortFilter').onchange=e=>{state.sort=e.target.value;render()};
$('#resetFilters').onclick=resetFilters;$('#emptyReset').onclick=resetFilters;
$('#loadMore').onclick=()=>{const count=state.limit;state.limit+=18;render();const firstNew=$$('.card-open')[count];firstNew?.focus({preventScroll:true})};
$('#componentGrid').onclick=e=>{const s=e.target.closest('.card-save'),o=e.target.closest('.card-open');if(s)toggleSave(s.dataset.id);else if(o)openComponent(o.dataset.id)};
function setDensity(v){state.density=v;$('#gridView').classList.toggle('active',v==='grid');$('#listView').classList.toggle('active',v==='list');$('#gridView').setAttribute('aria-pressed',v==='grid');$('#listView').setAttribute('aria-pressed',v==='list');render()}
$('#gridView').onclick=()=>setDensity('grid');$('#listView').onclick=()=>setDensity('list');
$('#mobileMenu').onclick=()=>{const open=$('#sidebar').classList.toggle('open');$('#mobileMenu').setAttribute('aria-expanded',open);syncSidebar()};$('#mobileBackdrop').onclick=closeMobile;
$('#navLibrary').onclick=()=>setView('all');
const surprise=()=>{const pool=filtered();openComponent((pool.length?pool:all)[Math.floor(Math.random()*(pool.length||all.length))].id)};
$('#randomSide').onclick=()=>{closeMobile();surprise()};$('#navPlayground').onclick=surprise;
$('#navCollections').onclick=()=>{resetFilters();$('#navLibrary').classList.remove('active');$('#navCollections').classList.add('active');$('#sectionEyebrow').textContent='Curated starting points';$('#libraryTitle').innerHTML='Collections';const sets=[{name:'Motion',text:'Text animations, interactions, and backgrounds.',glyph:'✳',cats:['typography','motion','backgrounds']},{name:'UI components',text:'Inputs, navigation, data, and feedback.',glyph:'◈',cats:['essentials','navigation','forms','data','feedback']},{name:'Layouts & spaces',text:'Responsive grids, rearrangeable panels, and device mockups.',glyph:'▧',cats:['layouts','mockups']}];$('#collectionsPanel').innerHTML=sets.map((x,i)=>`<button class="collection-tile" data-collection="${i}"><h3>${x.name}</h3><p>${x.text}</p></button>`).join('');$('#collectionsPanel').hidden=false;$('#collectionsPanel').onclick=e=>{const b=e.target.closest('[data-collection]');if(!b)return;state.collection=sets[Number(b.dataset.collection)].cats;state.limit=18;render();$$('.collection-tile').forEach(n=>n.classList.toggle('selected',n===b));$('#sectionEyebrow').textContent=sets[Number(b.dataset.collection)].name};scrollLibrary()};

const dialog=$('#componentDialog');
function updateDetailSave(){$('#detailSave').classList.toggle('saved',saved.has(current.id));$('#detailSave').setAttribute('aria-label',`${saved.has(current.id)?'Unsave':'Save'} ${current.name}`);$('#detailSave').setAttribute('aria-pressed',saved.has(current.id))}
function buildPreview(){const old=$('#previewViewport iframe');if(old)old.remove();const f=document.createElement('iframe');f.title=`Interactive ${current.name} demo`;f.setAttribute('sandbox','allow-scripts allow-downloads allow-popups allow-popups-to-escape-sandbox');f.srcdoc=iframeDocument(current);$('#previewViewport').append(f);f.onload=sendControls}
function sendControls(){const f=$('#previewViewport iframe');if(f?.contentWindow)f.contentWindow.postMessage({type:'noir-control',speed:demoSpeed,paused:demoPaused},'*')}
function updateCode(){if(!current)return;$('#codeContent').textContent=codeTab==='html'?current.html:codeTab==='css'?demoStyles(current):codeTab==='js'?(exportScript(current)||'// This component uses only HTML and CSS.'):fullExample(current);$$('[data-code]').forEach(b=>b.classList.toggle('active',b.dataset.code===codeTab))}
function setDetailTab(tab){detailTab=tab;$('#previewPane').hidden=tab!=='preview';$('#codePane').hidden=tab!=='code';$$('[data-detail-tab]').forEach(b=>b.classList.toggle('active',b.dataset.detailTab===tab));if(tab==='code')updateCode()}
function openComponent(id,hash=true){const c=all.find(x=>x.id===id);if(!c)return;current=c;demoSpeed=1;demoPaused=false;demoCanvas=theme;mobile=false;$('#detailTitle').textContent=c.name;$('#detailDescription').textContent=c.description;$('#detailCategory').textContent=catOf(c.category).name;$('#detailTags').innerHTML=c.tags.map(t=>`<span>${escapeHTML(t)}</span>`).join('');$('#detailSource').hidden=!c.inspiration;$('#detailSource').innerHTML=c.inspiration?`<span>Inspired by</span><a href="${escapeHTML(c.inspiration.url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(c.inspiration.name)} ↗</a>`:'';$('#speedControl').value=1;$('#speedValue').textContent='1×';$('#previewViewport').classList.remove('mobile');$('#desktopPreview').classList.add('active');$('#mobilePreview').classList.remove('active');$('#viewportLabel').textContent='Responsive canvas';$('#pauseDemo').innerHTML=icon('pause')+'<span>Pause animations</span>';$('#pauseDemo').title='Pause animations';$('#speedControl').title='Adjust CSS and Web Animation speed';syncCanvasButtons();updateDetailSave();codeTab='html';setDetailTab('preview');buildPreview();if(!dialog.open)dialog.showModal();dialog.scrollTop=0;closeMobile();if(hash)history.replaceState(null,'',`#component/${c.id}`)}
function closeDetail(){dialog.close()}
$('#closeDetail').onclick=closeDetail;dialog.addEventListener('close',()=>{$('#previewViewport').innerHTML='';current=null;if(location.hash.startsWith('#component/'))history.replaceState(null,'',location.pathname+location.search)});
$('#detailSave').onclick=()=>toggleSave(current.id);$$('[data-detail-tab]').forEach(b=>b.onclick=()=>setDetailTab(b.dataset.detailTab));$$('[data-code]').forEach(b=>b.onclick=()=>{codeTab=b.dataset.code;updateCode()});
$('#replayDemo').onclick=()=>{demoPaused=false;$('#pauseDemo').innerHTML=icon('pause')+'<span>Pause animations</span>';buildPreview();setDetailTab('preview')};
$('#pauseDemo').onclick=()=>{demoPaused=!demoPaused;$('#pauseDemo').innerHTML=icon(demoPaused?'play':'pause')+`<span>${demoPaused?'Resume':'Pause'} animations</span>`;sendControls()};
$('#speedControl').oninput=e=>{demoSpeed=Number(e.target.value);$('#speedValue').textContent=demoSpeed+'×';sendControls();updateCode()};
$$('[data-canvas]').forEach(b=>b.onclick=()=>{demoCanvas=b.dataset.canvas;syncCanvasButtons();buildPreview();updateCode()});
function previewSize(isMobile){mobile=isMobile;$('#previewViewport').classList.toggle('mobile',isMobile);$('#desktopPreview').classList.toggle('active',!isMobile);$('#mobilePreview').classList.toggle('active',isMobile);$('#viewportLabel').textContent=isMobile?'340 px · Mobile':'Responsive canvas'}
$('#desktopPreview').onclick=()=>previewSize(false);$('#mobilePreview').onclick=()=>previewSize(true);
async function copyText(text){try{await navigator.clipboard.writeText(text);notify('Code copied.')}catch{const input=document.createElement('textarea');input.value=text;input.style.cssText='position:fixed;left:-9999px';(dialog.open?dialog:document.body).append(input);input.select();const copied=document.execCommand('copy');input.remove();notify(copied?'Code copied.':'Select the code and copy it with your keyboard.')}}
$('#copyCode').onclick=()=>copyText($('#codeContent').textContent);
$('#downloadDemo').onclick=()=>{const blob=new Blob([fullExample(current)],{type:'text/html'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`noir-${current.id}.html`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);notify('Component downloaded. Open the HTML file to try it.')};
$('#nextComponent').onclick=()=>{const list=filtered().length?filtered():all;let i=list.findIndex(c=>c.id===current.id);openComponent(list[(i+1)%list.length].id)};

const searchDialog=$('#searchDialog');let searchItems=[],searchIndex=0;
function commandResults(){const q=$('#commandSearch').value.toLowerCase().trim();searchItems=all.filter(c=>!q||`${c.name} ${c.tags.join(' ')} ${catOf(c.category).name} ${c.inspiration?.name||''}`.toLowerCase().includes(q)).slice(0,8);searchIndex=0;$('#commandLabel').textContent=q?`${searchItems.length}${searchItems.length===8?'+':''} results`:'Components';$('#commandResults').innerHTML=searchItems.map((c,i)=>`<button class="command-result ${i===0?'selected':''}" data-command="${c.id}"><span>${icon(catOf(c.category).icon)}</span><div><strong>${escapeHTML(c.name)}</strong><small>${catOf(c.category).name}</small></div><span>↵</span></button>`).join('')||'<div class="command-empty">No matches yet. Try “text”, “card”, or “motion”.</div>'}
function openSearch(){if(dialog.open)dialog.close();$('#infoDialog').close();$('#commandSearch').value='';commandResults();searchDialog.showModal();$('#commandSearch').focus()}
$('#searchTrigger').onclick=openSearch;$('#commandSearch').oninput=commandResults;$('#closeSearch').onclick=()=>searchDialog.close();
$('#commandResults').onclick=e=>{const b=e.target.closest('[data-command]');if(b){searchDialog.close();openComponent(b.dataset.command)}};
$('#commandSearch').onkeydown=e=>{if((e.key==='ArrowDown'||e.key==='ArrowUp')&&searchItems.length){e.preventDefault();searchIndex=(searchIndex+(e.key==='ArrowDown'?1:-1)+searchItems.length)%searchItems.length;$$('.command-result').forEach((b,i)=>b.classList.toggle('selected',i===searchIndex));$$('.command-result')[searchIndex]?.scrollIntoView({block:'nearest'})}if(e.key==='Enter'&&searchItems[searchIndex]){searchDialog.close();openComponent(searchItems[searchIndex].id)}};

const docs=`<h2>Documentation</h2><p>NOIR contains ${all.length} components across ${categories.length} categories. All examples use black, white, and gray.</p><h3>Using a component</h3><ol><li>Browse or search the library. Press <kbd>⌘ / Ctrl K</kbd> to search.</li><li>Open a component to try its interactions, change the canvas, adjust animation speed, or check its mobile layout.</li><li>Copy HTML, CSS, or JavaScript from the Code tab. Choose <em>Full example</em> for a complete document, or download the HTML file.</li></ol><h3>Installation</h3><p>No packages required. Add the markup and styles to your page, then run the script after the markup. Adapt attributes and event handlers when using a framework.</p><h3>Motion studies</h3><p>New motion, typography, backgrounds, and layouts adapt animation concepts such as springs, staggering, gestures, and layout transitions into standalone NOIR examples. Source links appear in their detail panels.</p><h3>Light and dark</h3><p>Use the theme button to change the library and all component previews. The playground theme controls change component surfaces, text, and effects together. Exported CSS includes both palettes and follows system appearance unless a data-theme attribute selects a palette.</p><h3>Saved components</h3><p>Bookmarks are stored in this browser.</p><h3>Preview controls</h3><p>Animation controls apply to CSS and Web Animations. JavaScript timers and canvas effects follow their own scripts. Reduced motion is respected. Component content and product metrics are illustrative.</p><button class="button-primary" id="docsExplore">Browse components</button>`;
function openInfo(html){$('#infoContent').innerHTML=html;$('#infoDialog').showModal()}
function openDocs(){openInfo(docs);$('#docsExplore').onclick=()=>{$('#infoDialog').close();scrollLibrary()}}
$('#docsButton').onclick=openDocs;$('#footerDocs').onclick=openDocs;$('#closeInfo').onclick=()=>$('#infoDialog').close();
$('#shortcuts').onclick=()=>{openInfo(`<h2>Keyboard shortcuts</h2><div class="shortcut-row"><span>Search the entire library</span><kbd>⌘ / Ctrl + K</kbd></div><div class="shortcut-row"><span>Open search</span><kbd>/</kbd></div><div class="shortcut-row"><span>Navigate search results</span><kbd>↑ ↓</kbd></div><div class="shortcut-row"><span>Open selected component</span><kbd>Enter</kbd></div><div class="shortcut-row"><span>Close a dialog</span><kbd>Esc</kbd></div><p>Every button and control is keyboard accessible. Use Tab to move between them.</p>`)};
for(const d of [dialog,searchDialog,$('#infoDialog')])d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});
document.addEventListener('keydown',e=>{const typing=/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName)||document.activeElement?.isContentEditable;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}else if(e.key==='/'&&!typing&&!dialog.open&&!$('#infoDialog').open){e.preventDefault();openSearch()}});
window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#component/'))openComponent(location.hash.slice(11),false)});
syncSidebar();matchMedia('(max-width:800px)').addEventListener('change',syncSidebar);
render();
if(location.hash.startsWith('#component/'))openComponent(decodeURIComponent(location.hash.slice(11)),false);
